MATCH (p:AircraftModel {name:"North American P-51 Mustang"}), (b:AircraftModel {name:"Boeing 737-500"})

// Ensure the wingspan values are present and correct
FOREACH (_ IN CASE WHEN p.wingspan_metre IS NULL OR p.wingspan_metre = '' OR toFloat(p.wingspan_metre) <> 11.73 THEN [1] ELSE [] END |
  SET p.wingspan_metre = 11.73
)
FOREACH (_ IN CASE WHEN b.wingspan_metre IS NULL OR b.wingspan_metre = '' OR toFloat(b.wingspan_metre) <> 35.8 THEN [1] ELSE [] END |
  SET b.wingspan_metre = 35.8
)

// Compare the (now verified) wingspan values
WITH p, b, toFloat(p.wingspan_metre) AS pSpan, toFloat(b.wingspan_metre) AS bSpan
RETURN CASE WHEN pSpan > bSpan THEN p.name ELSE b.name END AS larger_wingspan_aircraft

MATCH (fa:FlightAccident)-[:DEPARTS_FROM]->(a:Airport)
WHERE fa.flight_number = 201 AND fa.name = "South African Airways Flight 201"
RETURN a.name AS airport_name;

MATCH (fa:FlightAccident)-[:destinedFor]->(a:Airport)
WHERE toLower(fa.description) CONTAINS "juvenal habyarimana" OR toLower(fa.description) CONTAINS "cyprien ntaryamira"
RETURN DISTINCT a.name AS airport_name, a.iata_code AS iata_code;

MATCH (fa:FlightAccident)-[:departsFrom]->(a:Airport)
WHERE fa.flight_number = 'SJ182' OR fa.flight_number = '574'
RETURN DISTINCT a.name AS airport_name;

MATCH (fa:FlightAccident)-[:operatedBy]->(op:Operator)
WHERE fa.flight_number CONTAINS '383' OR fa.name CONTAINS 'American Airlines Flight 383'
RETURN DISTINCT op.name AS operator;
